package dev.trentdb.execution.ddl;
import dev.trentdb.ast.*; import dev.trentdb.catalog.*; import dev.trentdb.execution.*; import dev.trentdb.parser.*; import dev.trentdb.planner.*; import dev.trentdb.planner.logical.*; import dev.trentdb.storage.*; import dev.trentdb.storage.wal.*; import dev.trentdb.transaction.*; import dev.trentdb.types.*; import java.nio.file.Path; import java.util.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.io.TempDir; import static org.junit.jupiter.api.Assertions.*;
class TransactionalDeletePipelineTest { @TempDir Path dir;
 @Test void writerSeesOwnDeleteOldSnapshotRetainsRowsAndNewSnapshotHidesThem() { try(var wal=WriteAheadLog.open(dir.resolve("delete.wal"))){var m=new TransactionManager(wal);var c=new Catalog();var s=new StorageManager();var create=m.startTransaction();exec(c,s,m,create,"CREATE TABLE people (id BIGINT)");m.commit(create);var insert=m.startTransaction();exec(c,s,m,insert,"INSERT INTO people VALUES (1)");m.commit(insert);var old=m.startTransaction();var writer=m.startTransaction();exec(c,s,m,writer,"DELETE FROM people");assertEquals(List.of(),rows(c,s,m,writer));assertEquals(List.of(List.of(1L)),rows(c,s,m,old));m.commit(writer);assertEquals(List.of(List.of(1L)),rows(c,s,m,old));assertEquals(List.of(),rows(c,s,m,m.startTransaction()));assertEquals(4,wal.recoverCommittedTransactions().getLast().writes().getFirst()[0]);}}
 @Test void rollbackAndLaterParticipantFailureRestoreRows() { try(var wal=WriteAheadLog.open(dir.resolve("rollback.wal"))){var m=new TransactionManager(wal);var c=new Catalog();var s=new StorageManager();var create=m.startTransaction();exec(c,s,m,create,"CREATE TABLE people (id BIGINT)");m.commit(create);var insert=m.startTransaction();exec(c,s,m,insert,"INSERT INTO people VALUES (1)");m.commit(insert);var rollback=m.startTransaction();exec(c,s,m,rollback,"DELETE FROM people WHERE id = 1");m.rollback(rollback);assertEquals(List.of(List.of(1L)),rows(c,s,m,m.startTransaction()));var failing=m.startTransaction();exec(c,s,m,failing,"DELETE FROM people WHERE id = 1");failing.enlist(new TransactionParticipant(){ public void prepareCommit(Transaction tx,long v){} public void commit(Transaction tx,long v){throw new IllegalStateException("fail");} public void rollback(Transaction tx){} });assertThrows(IllegalStateException.class,()->m.commit(failing));assertEquals(List.of(List.of(1L)),rows(c,s,m,m.startTransaction()));}}
 @Test void deleteWalIntentReplaysExplicitRowIds() { try(var wal=WriteAheadLog.open(dir.resolve("replay.wal"))){commit(wal,1,1,create());commit(wal,2,2,insert());commit(wal,3,3,delete());var c=new Catalog();var s=new StorageManager();var recovery=new DdlWalRecovery(c,s);recovery.replay(wal.recoverCommittedTransactions());assertEquals(List.of(),s.getTable(c.lookupTable(recovery.startReadTransaction(),name())).scanChunks());assertInstanceOf(DeleteStatement.class,new SqlParser().parse("DELETE FROM people WHERE id = 1"));}}
 @Test void deleteTombstonesRowsContainingNulls(){try(var wal=WriteAheadLog.open(dir.resolve("null.wal"))){var m=new TransactionManager(wal);var c=new Catalog();var s=new StorageManager();var tx=m.startTransaction();exec(c,s,m,tx,"CREATE TABLE nullable_people (id BIGINT, note TEXT)");m.commit(tx);var put=m.startTransaction();exec(c,s,m,put,"INSERT INTO nullable_people VALUES (1, NULL)");m.commit(put);var del=m.startTransaction();exec(c,s,m,del,"DELETE FROM nullable_people");m.commit(del);var read=m.startTransaction();assertEquals(List.of(),exec(c,s,m,read,"SELECT id, note FROM nullable_people").rows());}}
 @Test void predicateDeleteUsesWriterSnapshotNullSemanticsAndExplicitRowIds(){try(var wal=WriteAheadLog.open(dir.resolve("predicate.wal"))){var m=new TransactionManager(wal);var c=new Catalog();var s=new StorageManager();var create=m.startTransaction();exec(c,s,m,create,"CREATE TABLE people (id BIGINT, note TEXT)");m.commit(create);for(var sql:List.of("INSERT INTO people VALUES (1, 'keep')","INSERT INTO people VALUES (2, NULL)","INSERT INTO people VALUES (3, 'remove')")){var put=m.startTransaction();exec(c,s,m,put,sql);m.commit(put);}var old=m.startTransaction();var writer=m.startTransaction();exec(c,s,m,writer,"DELETE FROM people WHERE id = 2 AND note IS NULL");exec(c,s,m,writer,"DELETE FROM people WHERE id = 3 OR note = NULL");assertEquals(List.of(List.of(1L,"keep")),exec(c,s,m,writer,"SELECT id, note FROM people").rows());assertEquals(List.of(List.of(1L,"keep"),java.util.Arrays.asList(2L,null),List.of(3L,"remove")),exec(c,s,m,old,"SELECT id, note FROM people").rows());m.commit(writer);assertEquals(List.of(List.of(1L,"keep"),java.util.Arrays.asList(2L,null),List.of(3L,"remove")),exec(c,s,m,old,"SELECT id, note FROM people").rows());var read=m.startTransaction();assertEquals(List.of(List.of(1L,"keep")),exec(c,s,m,read,"SELECT id, note FROM people").rows());var zero=m.startTransaction();exec(c,s,m,zero,"DELETE FROM people WHERE id = 99");m.commit(zero);assertEquals(List.of(List.of(1L,"keep")),exec(c,s,m,m.startTransaction(),"SELECT id, note FROM people").rows());var own=m.startTransaction();exec(c,s,m,own,"INSERT INTO people VALUES (4, 'private')");exec(c,s,m,own,"DELETE FROM people WHERE id = 4");assertEquals(List.of(List.of(1L,"keep")),exec(c,s,m,own,"SELECT id, note FROM people").rows());m.commit(own);var rollback=m.startTransaction();exec(c,s,m,rollback,"DELETE FROM people WHERE id = 1");m.rollback(rollback);assertEquals(List.of(List.of(1L,"keep")),exec(c,s,m,m.startTransaction(),"SELECT id, note FROM people").rows());var recoveredCatalog=new Catalog();var recoveredStorage=new StorageManager();var recovery=new DdlWalRecovery(recoveredCatalog,recoveredStorage);recovery.replay(wal.recoverCommittedTransactions());var recovered=recoveredStorage.getTable(recoveredCatalog.lookupTable(recovery.startReadTransaction(),name())).scanChunks();assertEquals(1,recovered.size());assertEquals(1,recovered.getFirst().cardinality());assertEquals(1L,recovered.getFirst().column(0).getBigint(0));assertEquals(4,wal.recoverCommittedTransactions().get(4).writes().getFirst()[0]);}}
 @Test void predicateDeleteRejectsNonRowLocalAndNonBooleanConditions(){var c=new Catalog();var manager=new TransactionManager();var tx=manager.startTransaction();c.createTable(tx,new CreateTableStatement(name(),List.of(new ColumnDefinition("id",TypeName.BIGINT),new ColumnDefinition("note",TypeName.TEXT))));manager.commit(tx);var read=manager.startTransaction();var binder=new Binder(c);assertThrows(BinderException.class,()->binder.bind(read,new SqlParser().parse("DELETE FROM people WHERE lower(note) = 'x'")));assertThrows(BinderException.class,()->binder.bind(read,new SqlParser().parse("DELETE FROM people WHERE 1")));assertThrows(BinderException.class,()->binder.bind(read,new SqlParser().parse("DELETE FROM people WHERE EXISTS (SELECT id FROM people)")));assertInstanceOf(DeleteStatement.class,new SqlParser().parse("DELETE FROM people WHERE id = 1"));}

 private static QueryResult exec(Catalog c,StorageManager s,TransactionManager m,Transaction tx,String sql){return new QueryExecutor(s,new TransactionalDdlExecutor(c,s,m,tx)).execute(new LogicalPlanner().plan(new Binder(c).bind(tx,new SqlParser().parse(sql))));} private static List<List<Object>> rows(Catalog c,StorageManager s,TransactionManager m,Transaction tx){return exec(c,s,m,tx,"SELECT id FROM people").rows();}
 private static QualifiedName name(){return new QualifiedName(List.of("people"));} private static byte[] create(){return DdlWalPayload.createTable(new CreateTableStatement(name(),List.of(new ColumnDefinition("id",TypeName.BIGINT))));} private static TableCatalogEntry table(){return new TableCatalogEntry(new SchemaCatalogEntry("public"),"people",List.of(new ColumnCatalogEntry("id",LogicalType.BIGINT,0)));} private static byte[] insert(){return DdlWalPayload.insert(new BoundInsertStatement(table(),List.of(0),List.of(new BoundLiteralExpression(LogicalType.INTEGER,1L))));} private static byte[] delete(){return DdlWalPayload.delete(new BoundDeleteStatement(table()));} private static void commit(WriteAheadLog w,long id,long v,byte[] p){w.appendBegin(id);w.appendWrite(id,p);w.appendCommit(id,v);w.force();}
}
